var data = $input.first().json;

// Handle both: array from Supabase OR single object extracted by n8n
var session = null;
if (Array.isArray(data) && data.length > 0) {
  session = data[0];
} else if (data && typeof data === 'object' && data.id) {
  session = data;
}

if (!session) {
  throw new Error('Session not found');
}

return [{ json: session }];

var session = $('Extract Session').first().json;

var itemsRaw = $('Get Items In Machine').all();
var items = [];
for (var i = 0; i < itemsRaw.length; i++) {
  items.push(itemsRaw[i].json);
}

var machinesRaw = $('Get Machines In Route').all();
var machines = [];
for (var i = 0; i < machinesRaw.length; i++) {
  machines.push(machinesRaw[i].json);
}

var routesRaw = $('Get Routes').all();
var routes = [];
for (var i = 0; i < routesRaw.length; i++) {
  routes.push(routesRaw[i].json);
}

var currentItemIndex = session.current_item_index || 0;
var currentMachineId = session.current_machine_id;
var currentRouteId = session.current_route_id;
var pickDirection = session.pick_direction || 'forward';

var currentMachine = null;
var currentMachineSeq = 0;
for (var i = 0; i < machines.length; i++) {
  if (machines[i].id === currentMachineId) {
    currentMachine = machines[i];
    currentMachineSeq = machines[i].sequence;
    break;
  }
}

var currentRoute = null;
for (var i = 0; i < routes.length; i++) {
  if (routes[i].id === currentRouteId) {
    currentRoute = routes[i];
    break;
  }
}

var nextItem = null;
if (pickDirection === 'reverse') {
  for (var i = 0; i < items.length; i++) {
    if (items[i].sequence === currentItemIndex - 1) {
      nextItem = items[i];
      break;
    }
  }
} else {
  for (var i = 0; i < items.length; i++) {
    if (items[i].sequence === currentItemIndex + 1) {
      nextItem = items[i];
      break;
    }
  }
}

if (nextItem) {
  var newIndex = pickDirection === 'reverse' ? currentItemIndex - 1 : currentItemIndex + 1;
  var remaining = pickDirection === 'reverse' ? newIndex - 1 : items.length - newIndex;
  return [{
    json: {
      action: 'next_item',
      product_name: nextItem.product_name,
      quantity: nextItem.quantity,
      slot: nextItem.slot,
      machine_name: currentMachine ? currentMachine.machine_name : '',
      inventory_current: nextItem.inventory_current || 0,
      inventory_parlevel: nextItem.inventory_parlevel || 0,
      items_remaining: remaining,
      new_item_index: newIndex,
      new_machine_id: currentMachineId,
      new_route_id: currentRouteId,
      session_record_id: session.id,
      machine_complete: false,
      route_complete: false,
      session_complete: false
    }
  }];
}

var nextMachine = null;
for (var i = 0; i < machines.length; i++) {
  if (machines[i].sequence === currentMachineSeq + 1 && machines[i].status !== 'skipped') {
    nextMachine = machines[i];
    break;
  }
}

if (nextMachine) {
  return [{
    json: {
      action: 'next_machine',
      completed_machine: currentMachine ? currentMachine.machine_name : 'Machine',
      completed_machine_number: currentMachine ? currentMachine.machine_number : 0,
      completed_location: currentMachine ? currentMachine.location_name : '',
      next_machine_id: nextMachine.id,
      next_machine_name: nextMachine.machine_name,
      next_machine_number: nextMachine.machine_number,
      next_location: nextMachine.location_name,
      new_item_index: 0,
      new_machine_id: nextMachine.id,
      new_route_id: currentRouteId,
      session_record_id: session.id,
      machine_complete: true,
      route_complete: false,
      session_complete: false
    }
  }];
}

return [{
  json: {
    action: 'complete',
    completed_route: currentRoute ? currentRoute.route_name : 'Route',
    total_routes: routes.length,
    session_record_id: session.id,
    new_status: 'completed',
    new_item_index: currentItemIndex,
    new_machine_id: currentMachineId,
    new_route_id: currentRouteId,
    machine_complete: true,
    route_complete: true,
    session_complete: true
  }
}];

var stateData = $('Switch Action').first().json;

return [{
  json: {
    action: stateData.action,
    completed_machine: stateData.completed_machine,
    completed_location: stateData.completed_location,
    next_location: stateData.next_location,
    next_machine: stateData.next_machine_name,
    next_machine_number: stateData.next_machine_number,
    new_item_index: stateData.new_item_index,
    new_machine_id: stateData.new_machine_id,
    new_route_id: stateData.new_route_id,
    session_record_id: stateData.session_record_id,
    machine_complete: stateData.machine_complete,
    route_complete: stateData.route_complete,
    session_complete: stateData.session_complete
  }
}];

var data = $('Merge All Paths').first().json;

function formatSlotForTTS(slot) {
  if (!slot) return null;
  slot = String(slot);

  if (slot.indexOf('-') !== -1) {
    var parts = slot.split('-');
    var first = parseInt(parts[0], 10);
    var second = parseInt(parts[1], 10);
    if (!isNaN(first) && !isNaN(second)) {
      return 'slots ' + first + ' and ' + second;
    }
    return slot;
  }

  var num = parseInt(slot, 10);
  if (!isNaN(num)) {
    return 'slot ' + num;
  }

  return slot;
}

// Fix TTS pronunciation issues
function fixPronunciation(text) {
  if (!text) return text;
  // Fix "Can" pronounced as "Kahn" - replace with "Kan" for correct pronunciation
  // Only replace when it's a standalone word (not part of another word like "candy")
  text = text.replace(/\bCan\b/g, 'Kan');
  text = text.replace(/\bCAN\b/g, 'KAN');
  // Fix common abbreviations
  text = text.replace(/\boz\b/gi, 'ounce');
  text = text.replace(/\bct\b/gi, 'count');
  text = text.replace(/\bpk\b/gi, 'pack');
  return text;
}

// Random prefix for variety
function getRandomPrefix() {
  var prefixes = [
    'Next up: ',
    'OK, grab ',
    'Alright, ',
    'Got it. ',
    '',
    'Here we go: ',
    'Next: '
  ];
  return prefixes[Math.floor(Math.random() * prefixes.length)];
}

// Generate TTS-ready spoken response with variety
function generateSpoken(action, data, slotSpoken) {
  if (action === 'next_item') {
    var prefix = getRandomPrefix();
    var productName = fixPronunciation(data.product_name);
    var base = data.quantity + ' ' + productName + ', ' + slotSpoken;

    // Special case for last item
    if (data.items_remaining === 0) {
      var lastPhrases = [
        'Last one! ',
        'Final item: ',
        'And the last one: '
      ];
      prefix = lastPhrases[Math.floor(Math.random() * lastPhrases.length)];
    }
    return prefix + base;
  }

  if (action === 'next_machine') {
    var donePhrases = [
      'Nice! ',
      'Done! ',
      'Great! ',
      'Perfect! '
    ];
    var donePrefix = donePhrases[Math.floor(Math.random() * donePhrases.length)];
    // Use consistent full sentence for direction question
    return donePrefix + data.completed_machine + ' complete. Next up is ' + data.next_machine + ' at ' + data.next_location + '. Would you like to start at the top of the list for this machine, or the bottom?';
  }

  if (action === 'complete') {
    var completePhrases = [
      'All done! Great work on the ' + data.completed_route + ' route.',
      'Finished! ' + data.completed_route + ' route complete. Nice job!',
      'That\'s it! ' + data.completed_route + ' route is done.'
    ];
    return completePhrases[Math.floor(Math.random() * completePhrases.length)];
  }

  return null;
}

var output = {
  action: data.action,
  machine_complete: data.machine_complete || false,
  route_complete: data.route_complete || false,
  session_complete: data.session_complete || false
};

var slotSpoken = null;

if (data.action === 'next_item') {
  output.product_name = data.product_name;
  output.quantity = data.quantity;
  output.slot = data.slot;
  slotSpoken = formatSlotForTTS(data.slot);
  output.slot_spoken = slotSpoken;
  output.machine_name = data.machine_name || '';
  output.inventory_current = data.inventory_current || 0;
  output.inventory_parlevel = data.inventory_parlevel || 0;
  output.items_remaining = data.items_remaining;
}

if (data.action === 'next_machine') {
  output.completed_machine = data.completed_machine;
  output.completed_location = data.completed_location;
  output.next_location = data.next_location;
  output.next_machine = data.next_machine;
  output.next_machine_id = data.new_machine_id;  // Include next machine ID for frontend state
  output.next_machine_number = data.next_machine_number;
}

if (data.action === 'complete') {
  output.completed_route = data.completed_route;
  output.total_routes = data.total_routes;
  output.message = 'All routes finished';
}

// Add spoken field for fast path (skips second AI call)
output.spoken = generateSpoken(data.action, data, slotSpoken);

return [{ json: output }];
